insert into public.exercises(id,name,description,muscle_group,equipment,tracking_type) values('10000000-0000-4000-8000-000000000084','Incline dumbbell fly','Set the bench to roughly 30 degrees, hold a fixed soft bend in the elbows the whole rep, and open the arms until the dumbbells reach chest level before hugging them back together over the collarbones.','Chest','Dumbbell','weighted'),('10000000-0000-4000-8000-000000000085','Decline dumbbell press','Hook your legs in before you kick the dumbbells up, press straight over the lower chest rather than back towards your face, and drop the bells out to the sides when you finish instead of trying to sit up with them.','Chest','Dumbbell','weighted'),('10000000-0000-4000-8000-000000000086','High cable fly','Set both pulleys above shoulder height, take a staggered stance and lean slightly into the cables, then sweep the handles down and across until your wrists cross in front of your hips.','Chest','Cable','weighted'),('10000000-0000-4000-8000-000000000087','Barbell floor press','Lie flat under the rack with knees bent, lower until the backs of your triceps rest on the floor, pause a full beat there, then press from a dead stop with the elbows tucked near 45 degrees.','Chest','Barbell','weighted'),('10000000-0000-4000-8000-000000000088','Smith machine bench press','Slide the bench until the fixed bar path lands on your lower chest, set the safety catches just below that point, and twist the bar to unrack - the locked path lets you push the last set closer to failure without a spotter.','Chest','Machine','weighted'),('10000000-0000-4000-8000-000000000089','Decline push-up','Put your feet on a bench or box so the hips stay in line with the shoulders, and lower until the chest is just off the floor - the higher the feet, the more the upper chest and front delts take.','Chest','Bodyweight','bodyweight'),('10000000-0000-4000-8000-000000000090','Band chest press','Anchor the band at chest height behind you and run it under your armpits, then press forward until the hands nearly touch, stepping further from the anchor rather than choking up on the band when the top feels light.','Chest','Band','bodyweight'),('10000000-0000-4000-8000-000000000091','Kettlebell floor press','Roll onto your side to pick the bell up safely, press with the handle sitting in the heel of the hand and the wrist dead straight, and let the upper arm settle on the floor for a beat between reps.','Chest','Kettlebell','weighted'),('10000000-0000-4000-8000-000000000092','T-bar row','Straddle the loaded end of the bar with a close V-handle under your sternum, hinge to roughly 45 degrees, and pull the handle into your lower ribs while the torso angle stays frozen.','Back','Barbell','weighted'),('10000000-0000-4000-8000-000000000093','Rack pull','Set the pins or blocks just below the kneecap, brace as if for a deadlift, and drive to lockout while dragging the bar up the thighs so the lats keep it pinned to your body.','Back','Barbell','weighted'),('10000000-0000-4000-8000-000000000094','Sumo deadlift','Take a wide stance with shins vertical and hands gripping inside the knees, then push the floor apart and open the hips as the bar breaks the ground rather than letting the hips shoot up first.','Legs','Barbell','weighted'),('10000000-0000-4000-8000-000000000095','Trap bar deadlift','Stand centred in the frame with the handles level at mid-thigh, sit into the hips and push the floor away, keeping the bar from tipping forward or back so both handles rise together.','Legs','Barbell','weighted'),('10000000-0000-4000-8000-000000000096','Seal row','Lie face down on a raised bench with the bar hanging clear of the floor and row it to the underside of the bench, keeping your chest glued to the pad so no leg drive or torso swing can help.','Back','Barbell','weighted'),('10000000-0000-4000-8000-000000000097','Back extension','Set the pad just below the hip crease, fold the torso down under control until you feel the hamstrings and erectors load, then extend only until your body is one straight line instead of arching past it.','Back','Bodyweight','bodyweight'),('10000000-0000-4000-8000-000000000098','Kettlebell gorilla row','Set two bells between your feet, hinge until the torso is near parallel to the floor, and row one bell to the hip while the other stays planted on the ground as a brace, alternating sides each rep.','Back','Kettlebell','weighted'),('10000000-0000-4000-8000-000000000099','Band pull-apart','Hold the band at shoulder width with straight arms out in front, then pull it apart to your chest by driving the shoulder blades together until the band touches the sternum, and let it return slowly under tension.','Shoulders','Band','bodyweight'),('10000000-0000-4000-8000-000000000100','Band lat pulldown','Anchor the band overhead and kneel far enough back that it stays under tension at the top, then pull the ends down past your ears to collarbone height with the elbows driving toward your ribs.','Back','Band','bodyweight'),('10000000-0000-4000-8000-000000000101','Band seated row','Sit with legs straight and the band looped around your feet, sit tall, and row both ends to your waist until your hands reach the ribs, then let the band draw the arms fully forward to stretch the lats.','Back','Band','bodyweight'),('10000000-0000-4000-8000-000000000102','Shoulder press machine','Set the seat so the handles start level with your shoulders, press up until the elbows are just short of lockout, and lower under control until you feel a stretch rather than letting the stack touch down between reps.','Shoulders','Machine','weighted'),('10000000-0000-4000-8000-000000000103','Reverse pec deck','Sit with your chest against the pad and the handles set level with your shoulders, then sweep your arms out and back with the elbow angle locked, stopping once your hands reach the plane of your torso.','Shoulders','Machine','weighted'),('10000000-0000-4000-8000-000000000104','Upright row','Pull the bar up the front of your body with a grip a little wider than shoulder width, leading with the elbows and stopping when the upper arms reach shoulder height, which keeps the movement out of a painful pinch.','Shoulders','Barbell','weighted'),('10000000-0000-4000-8000-000000000105','Cable rear delt fly','Set both pulleys at shoulder height and take the handles crossed in front of you, then pull them apart and back in a wide arc with nearly straight arms until your hands finish in line with your torso.','Shoulders','Cable','weighted'),('10000000-0000-4000-8000-000000000106','Barbell shrug','Hold the bar at arm''s length just in front of your thighs and shrug straight up toward your ears with the elbows locked, pausing at the top instead of rolling the shoulders in a circle.','Shoulders','Barbell','weighted'),('10000000-0000-4000-8000-000000000107','Landmine press','With one end of the bar anchored in a corner or landmine sleeve, press the other end from the front of your shoulder up and slightly across your midline, finishing with the arm extended along the same diagonal as the bar.','Shoulders','Barbell','weighted'),('10000000-0000-4000-8000-000000000108','Pike push-up','From a pike with hips high and hands about shoulder width, bend the elbows to bring the crown of your head toward the floor just ahead of your hands, then press back up; elevating your feet shifts more bodyweight onto the delts.','Shoulders','Bodyweight','bodyweight'),('10000000-0000-4000-8000-000000000109','Kettlebell overhead press','Start in the rack with the bell resting on your forearm, press up while rotating the wrist so the palm faces forward at lockout, and keep the ribs pulled down rather than leaning back to finish the rep.','Shoulders','Kettlebell','weighted'),('10000000-0000-4000-8000-000000000110','Hack squat','Set your feet mid-platform with hips and upper back pinned to the pad, descend until the thighs pass parallel, and drive up without letting your lower back peel off the backrest.','Legs','Machine','weighted'),('10000000-0000-4000-8000-000000000111','Dumbbell split squat','Hold a long staggered stance with both feet flat and drop straight down until the rear knee brushes the floor, resetting nothing between reps so the feet never shuffle.','Legs','Dumbbell','weighted'),('10000000-0000-4000-8000-000000000112','Single-leg Romanian deadlift','Hinge over the working leg while the free leg extends behind you as a counterweight, keeping the hips square to the floor until the hamstring stretches, then stand fully tall.','Legs','Dumbbell','weighted'),('10000000-0000-4000-8000-000000000113','Nordic hamstring curl','Anchor the ankles and keep the hips extended in a straight line from knee to shoulder while lowering as slowly as you can, catching yourself with the hands at the end.','Legs','Bodyweight','bodyweight'),('10000000-0000-4000-8000-000000000114','Glute-ham raise','Set the footplate so the knees sit just behind the pad, then once the torso passes parallel pull yourself upright with the hamstrings rather than hinging at the hips.','Legs','Bodyweight','bodyweight'),('10000000-0000-4000-8000-000000000115','Cable glute kickback','Strap the ankle cuff to a low pulley, hinge slightly forward over the standing leg, and push the working leg back to full hip extension without arching the lower back to finish the rep.','Legs','Cable','weighted'),('10000000-0000-4000-8000-000000000116','Kettlebell front squat','Rack two bells on the backs of your forearms with the elbows tucked tight to the ribs, then squat between the knees while resisting the bells pulling your chest down.','Legs','Kettlebell','weighted'),('10000000-0000-4000-8000-000000000117','Lateral band walk','Loop the band above the knees or around the ankles, sink into a quarter-squat, and take small controlled steps sideways so the band never goes slack between steps.','Legs','Band','bodyweight'),('10000000-0000-4000-8000-000000000118','Smith machine squat','Walk the feet slightly forward of the bar so the fixed path lets you sit straight down, and rotate the hooks fully clear of the catches before starting the first rep.','Legs','Machine','weighted'),('10000000-0000-4000-8000-000000000119','Preacher curl','Set the pad so its top edge sits under your armpits and stop just short of a straight arm at the bottom, keeping tension on the biceps in its most stretched position.','Arms','Barbell','weighted'),('10000000-0000-4000-8000-000000000120','Incline dumbbell curl','Lie back on a bench set near 45 degrees and let the dumbbells hang behind your torso, curling without letting the elbows drift forward so the long head stays loaded in the stretch.','Arms','Dumbbell','weighted'),('10000000-0000-4000-8000-000000000121','Reverse curl','Curl with a knuckles-up grip and keep the wrists locked straight instead of letting them roll back, which shifts the load onto the brachialis and forearm extensors.','Arms','Barbell','weighted'),('10000000-0000-4000-8000-000000000122','Cable hammer curl','Curl a rope from a low pulley with palms facing each other, pulling the rope ends slightly apart at the top and stopping short of the bottom so the cable never goes slack.','Arms','Cable','weighted'),('10000000-0000-4000-8000-000000000123','Preacher curl machine','Line the machine''s pivot up with your elbows and set the seat so the pad supports the whole upper arm, then curl to full contraction and lower under control without letting the elbows slide up the pad.','Arms','Machine','weighted'),('10000000-0000-4000-8000-000000000124','Band curl','Stand on the middle of the band at hip width and curl against resistance that climbs toward the top, pausing at peak contraction where the band pulls hardest.','Arms','Band','bodyweight'),('10000000-0000-4000-8000-000000000125','Wrist curl','Rest your forearms along a bench with the wrists just past the edge, let the bar roll open to the fingertips, then curl it back up without lifting the forearms off the bench.','Arms','Barbell','weighted'),('10000000-0000-4000-8000-000000000126','Reverse wrist curl','With the forearm supported and the palm facing down, raise the back of the hand toward the ceiling and pause at the top, using far lighter weight than a normal wrist curl.','Arms','Dumbbell','weighted'),('10000000-0000-4000-8000-000000000127','Triceps kickback','Hinge until your torso is close to parallel with the floor and pin the upper arm against your side so the only motion is the elbow straightening to a hard lockout.','Arms','Dumbbell','weighted'),('10000000-0000-4000-8000-000000000128','Bench dip','Hands on a bench behind you and heels on the floor, lower until the upper arms reach roughly parallel while keeping your back brushing the bench rather than drifting forward.','Arms','Bodyweight','bodyweight'),('10000000-0000-4000-8000-000000000129','Triceps extension machine','Set the seat height so your elbows line up with the pivot, then press to a full lockout without letting your shoulders lift away from the back pad.','Arms','Machine','weighted'),('10000000-0000-4000-8000-000000000130','Band triceps pushdown','Anchor the band above head height, tuck the elbows to your ribs, and push down to full extension where band tension peaks, stepping back from the anchor to make it harder.','Arms','Band','bodyweight'),('10000000-0000-4000-8000-000000000131','Plank','Set your elbows directly under your shoulders and tuck the ribs down toward the hips until the lower back flattens; the set ends the moment the hips start to sag or hike, not when the clock runs out.','Core','Bodyweight','bodyweight'),('10000000-0000-4000-8000-000000000132','Side plank','Stack the top shoulder, hip and ankle over the bottom ones and drive the down-side elbow into the floor to push the bottom hip up, so the obliques hold the line instead of the shoulder sinking into it.','Core','Bodyweight','bodyweight'),('10000000-0000-4000-8000-000000000133','Hanging leg raise','From a dead hang, tilt the pelvis backwards before the legs travel and lift straight legs to at least hip height, lowering slowly enough that the body never begins to swing.','Core','Bodyweight','bodyweight'),('10000000-0000-4000-8000-000000000134','Ab wheel rollout','Rolling out from your knees, travel only as far as you can before the lower back starts to arch, then return by pushing the wheel down into the floor and pulling the ribs toward the hips.','Core','Bodyweight','bodyweight'),('10000000-0000-4000-8000-000000000135','Sit-up','With the knees bent and feet lightly anchored, peel the spine off the floor one segment at a time until the torso is vertical, then resist the way down instead of dropping back.','Core','Bodyweight','bodyweight'),('10000000-0000-4000-8000-000000000136','Pallof press','Stand side-on to a band anchored at chest height and press the handle straight out from your sternum, refusing the pull that wants to rotate your ribcage back toward the anchor - full extension is the hardest point, so pause there.','Core','Cable','weighted'),('10000000-0000-4000-8000-000000000137','Ab crunch machine','Set the seat so the pad''s pivot lines up with your navel, then shorten the distance between ribcage and pelvis by flexing the spine rather than hauling the pad down with your arms or folding at the hips.','Core','Machine','weighted'),('10000000-0000-4000-8000-000000000138','Suitcase carry','Hold one heavy kettlebell at your side and walk a set distance with shoulders and hips level, letting nothing tip toward or away from the bell - the side without the weight is the side doing the work.','Core','Kettlebell','weighted'),('10000000-0000-4000-8000-000000000139','Landmine rotation','With one end of the bar in a landmine and arms extended in front of the chest, sweep the bar from hip to hip by pivoting the trailing foot and turning the whole trunk, rather than steering it with the shoulders alone.','Core','Barbell','weighted'),('10000000-0000-4000-8000-000000000140','Russian twist','Sit leaning back near 45 degrees with the feet off the floor and rotate a dumbbell from hip to hip, turning the ribcage with the arms so the obliques move the weight instead of shuffling it across a static torso.','Core','Dumbbell','weighted'),('10000000-0000-4000-8000-000000000141','Hollow body hold','Press the lower back flat into the floor first, then extend the arms overhead and the legs out only as far as that contact survives, re-bending the knees the instant the back lifts.','Core','Bodyweight','bodyweight'),('10000000-0000-4000-8000-000000000142','Power clean','Break the bar off the floor with the same patient hinge you would use for a deadlift, then snap the hips through and pull yourself under to catch it on the front delts in a quarter squat with the elbows whipped high.','Full body','Barbell','weighted'),('10000000-0000-4000-8000-000000000143','Clean and jerk','Stand the clean all the way up and reset your breath before the jerk, then dip a few inches straight down over the heels and drive hard enough that you can punch your head through and lock the elbows as the feet split.','Full body','Barbell','weighted'),('10000000-0000-4000-8000-000000000144','Barbell snatch','Take a wide hook grip, sweep the bar into the hips and keep it brushing the body, then turn the arms over fast so you receive it locked overhead with the shoulders actively pushing up into the bar.','Full body','Barbell','weighted'),('10000000-0000-4000-8000-000000000145','Thruster','From the front rack, squat to full depth and let the drive out of the hole carry straight into the press so the bar never pauses at the shoulders on the way overhead.','Full body','Barbell','weighted'),('10000000-0000-4000-8000-000000000146','Burpee','Drop your chest and thighs flat to the floor, then jump the feet back under your hips and stand or jump in one continuous motion rather than pausing at the top of a push-up.','Full body','Bodyweight','bodyweight'),('10000000-0000-4000-8000-000000000147','Farmers walk','Deadlift the weights up, pull the shoulders back and lock the ribs down, then cover distance or time with short, quick steps and no swinging or leaning toward the heavier side.','Full body','Dumbbell','weighted'),('10000000-0000-4000-8000-000000000148','Kettlebell snatch','Hike the bell back between the legs, pull it high and close, then punch your hand around the handle at the top so the bell rolls onto the back of the forearm instead of banging down on the wrist.','Full body','Kettlebell','weighted'),('10000000-0000-4000-8000-000000000149','Turkish get-up','Keep your eyes locked on the overhead bell as you roll to the elbow, post to the hand, bridge the hips and sweep the back leg through to a lunge before standing, then reverse the exact same steps down.','Full body','Kettlebell','weighted'),('10000000-0000-4000-8000-000000000150','Dumbbell snatch','Hinge and pull one dumbbell from between the feet in a single motion, keeping it tight to the body, and punch the hand straight up so you finish with the arm locked out and the shoulder packed overhead.','Full body','Dumbbell','weighted') on conflict(id) do nothing;update public.exercises set description='Begin with your palms facing you and rotate them outward as you press, so the front and side delts each take a share of every rep.' where owner_id is null and name='Arnold press';update public.exercises set description='Same machine with an underhand grip, and because the biceps pitch in you should need noticeably less assistance than on assisted pull-ups.' where owner_id is null and name='Assisted chin-up';update public.exercises set description='More assistance weight makes the rep easier, so log the pad setting and drive that number down over the weeks rather than up.' where owner_id is null and name='Assisted dip';update public.exercises set description='Kneel or stand on the pad and log the assistance weight — a lower number is a harder set, so the goal is shrinking it week to week.' where owner_id is null and name='Assisted pull-up';update public.exercises set description='Take a big breath and brace before you descend, sit down between your hips, and make your chest and hips rise at the same rate out of the hole.' where owner_id is null and name='Back squat';update public.exercises set description='Pin your shoulder blades down and back into the bench, touch the bar to your lower chest, and press it back up over your shoulder joint rather than straight vertically.' where owner_id is null and name='Barbell bench press';update public.exercises set description='Keep your elbows pinned against your ribs and stop the shoulders from swinging the bar up — if your hips are moving, the weight is too heavy.' where owner_id is null and name='Barbell curl';update public.exercises set description='Rest the bench under your shoulder blades with your chin tucked and finish each rep by squeezing your glutes until your torso is parallel to the floor, never by arching your back.' where owner_id is null and name='Barbell hip thrust';update public.exercises set description='Hinge to roughly 45 degrees and pull the bar into your lower ribs without letting your torso rise up to meet it.' where owner_id is null and name='Barbell row';update public.exercises set description='Rotate through your ribcage to bring the shoulder toward the opposite knee, moving slowly rather than pedalling for speed.' where owner_id is null and name='Bicycle crunch';update public.exercises set description='Reach your arms forward as a counterbalance and go as deep as you can while keeping both heels flat on the floor.' where owner_id is null and name='Bodyweight squat';update public.exercises set description='Put the rear foot on the bench and step the front foot far enough forward that your front shin stays close to vertical at the bottom.' where owner_id is null and name='Bulgarian split squat';update public.exercises set description='Stagger your stance with the pulleys at chest height and bring your hands together past the midline, where cables hold tension that dumbbells lose.' where owner_id is null and name='Cable chest fly';update public.exercises set description='Kneel with the rope beside your head, keep your hips fixed in place, and crunch by rounding your spine down one rib at a time.' where owner_id is null and name='Cable crunch';update public.exercises set description='Constant cable tension makes the bottom of the rep as hard as the middle, so settle at full stretch for a moment instead of bouncing out of it.' where owner_id is null and name='Cable curl';update public.exercises set description='Start with the handle across your body so the cable loads the bottom of the range where dumbbells go slack, then raise out and up.' where owner_id is null and name='Cable lateral raise';update public.exercises set description='Pivot your back foot and rotate from the hips and ribs, keeping your arms fairly straight so the core does the turning rather than the shoulders.' where owner_id is null and name='Cable woodchop';update public.exercises set description='Set the seat so the handles line up with mid-chest rather than your throat, and press without letting your shoulders roll forward off the back pad.' where owner_id is null and name='Chest press machine';update public.exercises set description='The pad takes your lower back out of the lift entirely, so chase a full stretch at the bottom and a hard squeeze at the top with zero body english.' where owner_id is null and name='Chest-supported dumbbell row';update public.exercises set description='The underhand grip brings the biceps in, which is why most people out-rep their pull-ups here — keep driving the elbows down and back.' where owner_id is null and name='Chin-up';update public.exercises set description='Grip just inside shoulder width and keep your elbows tucked near your ribs — the tuck is what shifts the work to the triceps, not the narrow hands.' where owner_id is null and name='Close-grip bench press';update public.exercises set description='Brace the back of your upper arm against the inside of your thigh so nothing else can help, and take three slow seconds to lower.' where owner_id is null and name='Concentration curl';update public.exercises set description='Curl your ribcage a few inches toward your pelvis rather than hauling your whole torso up, and keep a fist of space under your chin.' where owner_id is null and name='Crunch';update public.exercises set description='Press your lower back flat into the floor and keep it there while you extend one arm and the opposite leg — if it lifts, shorten the reach.' where owner_id is null and name='Dead bug';update public.exercises set description='Pull the slack out of the bar before you move it, then push the floor away and keep the bar dragging up your shins and thighs the whole way.' where owner_id is null and name='Deadlift';update public.exercises set description='Hook your legs in before you unrack, then press slightly toward your feet so the bar follows the natural path the decline angle gives you.' where owner_id is null and name='Decline barbell bench press';update public.exercises set description='Put your hands together under your sternum and keep your elbows brushing your sides so the triceps take the load instead of the shoulders.' where owner_id is null and name='Diamond push-up';update public.exercises set description='Lean your torso forward and let the elbows flare a little to bias the chest; staying bolt upright makes it a triceps exercise instead.' where owner_id is null and name='Dip';update public.exercises set description='Kick the dumbbells up with your knees, lower until they sit level with your chest for a deeper stretch than a bar allows, and press without clanging them together.' where owner_id is null and name='Dumbbell bench press';update public.exercises set description='Supinate as you curl — turning your pinky up at the top brings in the biceps'' second job of rotating the forearm.' where owner_id is null and name='Dumbbell curl';update public.exercises set description='The floor stops your upper arms early, so pause when your triceps touch down and press from a dead stop — the friendliest chest press for a cranky shoulder.' where owner_id is null and name='Dumbbell floor press';update public.exercises set description='Hold one fixed soft bend in your elbows and open your arms in a wide arc — the moment the elbows start bending further, it has turned into a press.' where owner_id is null and name='Dumbbell fly';update public.exercises set description='Step out far enough that your front knee stacks over the ankle, drop the back knee toward the floor, and drive back up through the front heel.' where owner_id is null and name='Dumbbell lunge';update public.exercises set description='Keep your hips low and your arms nearly straight as you reach the dumbbell back past your head, hunting the long stretch through the lats and ribcage.' where owner_id is null and name='Dumbbell pullover';update public.exercises set description='Start with the dumbbells at ear height and press up and slightly inward, stopping just short of banging them together overhead.' where owner_id is null and name='Dumbbell shoulder press';update public.exercises set description='Shrug straight up toward your ears and hold the top for a beat; rolling your shoulders backward adds nothing but joint wear.' where owner_id is null and name='Dumbbell shrug';update public.exercises set description='Drive entirely through the foot on the box without pushing off the trailing leg, and lower yourself under control instead of dropping back down.' where owner_id is null and name='Dumbbell step-up';update public.exercises set description='The angled grip takes strain off the wrists, so if wrist discomfort is what limits your straight-bar curls you can usually load this one heavier.' where owner_id is null and name='EZ-bar curl';update public.exercises set description='Set the rope above head height and pull it apart toward your forehead, finishing with your knuckles beside your ears and your elbows high.' where owner_id is null and name='Face pull';update public.exercises set description='Raise to eye level and keep your ribs pulled down, or the movement quietly becomes a lower-back swing.' where owner_id is null and name='Front raise';update public.exercises set description='Keep your elbows high so the bar stays locked on the shelf of your front delts — the rep is lost the instant your elbows drop.' where owner_id is null and name='Front squat';update public.exercises set description='Bring your heels close to your hips and hold the top for a beat until the glutes are what cramps, not the hamstrings.' where owner_id is null and name='Glute bridge';update public.exercises set description='Hug the dumbbell tight to your chest as a counterweight — it is what lets you sit straight down between your knees and stay upright.' where owner_id is null and name='Goblet squat';update public.exercises set description='Use far less weight than you squat, hinge back with a rigid spine, and end the descent the moment your back wants to round.' where owner_id is null and name='Good morning';update public.exercises set description='The neutral grip held throughout targets the brachialis and forearm, which is why your hammer numbers usually beat your supinated curls.' where owner_id is null and name='Hammer curl';update public.exercises set description='Kill the swing by tilting your pelvis under first, then lift your knees past hip height on every rep instead of just below it.' where owner_id is null and name='Hanging knee raise';update public.exercises set description='Press your knees outward against the pads and lean your torso slightly forward to bring the upper glutes into the movement.' where owner_id is null and name='Hip abduction';update public.exercises set description='Squeeze the pads together under control and only let them open as far as your inner thighs stretch comfortably.' where owner_id is null and name='Hip adduction';update public.exercises set description='Set the bench around 30 degrees and touch the bar just below your collarbone; any steeper and the front delts take over from the upper chest.' where owner_id is null and name='Incline barbell bench press';update public.exercises set description='Let the dumbbells travel wide and low at the bottom for a stretch the barbell can''t give, then press them up and slightly toward each other.' where owner_id is null and name='Incline dumbbell press';update public.exercises set description='Hands on a bench or bar takes load off, so progress by lowering the surface height rather than only adding reps.' where owner_id is null and name='Incline push-up';update public.exercises set description='Set a bar at hip height and hold a rigid plank as you pull your chest to it; walk your feet further out to make the set harder.' where owner_id is null and name='Inverted row';update public.exercises set description='Guide the bell close to your body and punch your hand through it so it lands softly in the rack position instead of banging your forearm.' where owner_id is null and name='Kettlebell clean';update public.exercises set description='This is a hip snap, not a squat or a front raise — hike the bell back past your thighs and let the glutes float it up to chest height.' where owner_id is null and name='Kettlebell swing';update public.exercises set description='Pin your thighs under the pad, pull the bar to your upper chest by driving your elbows down, and fight the stretch on the way back up.' where owner_id is null and name='Lat pulldown';update public.exercises set description='Lead with your elbows to about shoulder height and lower slowly — swinging a heavier dumbbell just hands the set to your traps.' where owner_id is null and name='Lateral raise';update public.exercises set description='Line your knee joint up with the machine''s pivot and pause a beat at full lockout, where the quads are working hardest.' where owner_id is null and name='Leg extension';update public.exercises set description='Place your feet mid-platform, stop lowering the moment your hips start to tuck under, and leave a soft bend in the knees at the top.' where owner_id is null and name='Leg press';update public.exercises set description='Pull from the bottom pulleys up and inward to about chin height so the squeeze lands on the upper chest.' where owner_id is null and name='Low cable fly';update public.exercises set description='Keep your hips pressed flat into the pad — lifting them to finish the curl just hands the rep over to your lower back.' where owner_id is null and name='Lying leg curl';update public.exercises set description='Set the chest pad so your arms reach full extension at the start, then row until your hands meet your torso and let your shoulder blades move with it.' where owner_id is null and name='Machine row';update public.exercises set description='Brace a hand and knee on the bench and pull the dumbbell toward your hip rather than your armpit, without twisting your torso to finish the rep.' where owner_id is null and name='One-arm dumbbell row';update public.exercises set description='Face away from the stack with the rope behind your head and step out far enough that tension never disappears in the stretched position.' where owner_id is null and name='Overhead cable extension';update public.exercises set description='Squeeze your glutes so the lower back can''t arch, pull your head back out of the bar''s way, and finish with the bar stacked over your mid-foot.' where owner_id is null and name='Overhead press';update public.exercises set description='Overhead is where the long head of the triceps stretches, so let the dumbbell sink deep behind your head while your elbows stay pointed forward.' where owner_id is null and name='Overhead triceps extension';update public.exercises set description='Keep your back flat against the pad and drive with your elbows or upper arms instead of gripping the handles hard, which turns it into an arm exercise.' where owner_id is null and name='Pec deck';update public.exercises set description='Every rep starts from a dead stop on the floor with your back flat and parallel — explosive pull, full reset, repeat.' where owner_id is null and name='Pendlay row';update public.exercises set description='Overhand grip just outside shoulder width, start from a full dead hang, and pull until your chin clears the bar without kipping your legs.' where owner_id is null and name='Pull-up';update public.exercises set description='Dip a few inches with vertical shins, drive hard with the legs, and let your arms take over only once the bar passes your forehead.' where owner_id is null and name='Push press';update public.exercises set description='Hold a straight line from head to heels with elbows at roughly 45 degrees to your torso — once your hips start sagging, the set is finished.' where owner_id is null and name='Push-up';update public.exercises set description='Roll your pelvis up off the floor so the hips actually lift — swinging your knees toward your chest moves nothing.' where owner_id is null and name='Reverse crunch';update public.exercises set description='Hinge until your chest is nearly parallel to the floor and open your arms wide with the thumbs turned down, feeling it behind the shoulders rather than between the blades.' where owner_id is null and name='Reverse dumbbell fly';update public.exercises set description='Stepping backward keeps the front knee much quieter than a forward lunge, which makes this the friendlier option for sore knees.' where owner_id is null and name='Reverse lunge';update public.exercises set description='Push your hips straight back with soft knees and a flat back, and stop when your hamstrings run out of stretch, not when the plates reach the floor.' where owner_id is null and name='Romanian deadlift';update public.exercises set description='Sit tall, allow a small forward lean at the stretch, and pull the handle to your navel — rocking backward for extra reps is borrowed, not earned.' where owner_id is null and name='Seated cable row';update public.exercises set description='Bent knees shift the work onto the soleus underneath, which responds best to higher reps and a long pause in the stretched position.' where owner_id is null and name='Seated calf raise';update public.exercises set description='The seated position pre-stretches the hamstrings at the hip, so keep your hips pinned to the pad and curl deep underneath the seat.' where owner_id is null and name='Seated leg curl';update public.exercises set description='Let the working shoulder travel forward at the stretch, then pull it all the way back through a range a two-handed row can''t reach.' where owner_id is null and name='Single-arm cable row';update public.exercises set description='Stand on a step so your heel can drop well below your toes, hold something for balance, and use the full range one leg at a time.' where owner_id is null and name='Single-leg calf raise';update public.exercises set description='Angle your upper arms slightly back toward your head instead of straight up, so the triceps stay loaded at the top rather than resting on the joint.' where owner_id is null and name='Skull crusher';update public.exercises set description='Straight knees load the gastrocnemius, so sink into a full stretch at the bottom and pause at the top rather than bouncing through reps.' where owner_id is null and name='Standing calf raise';update public.exercises set description='Lock your elbows and hinge slightly forward, sweeping the bar down to your thighs in a wide arc so the lats work without any help from the biceps.' where owner_id is null and name='Straight-arm pulldown';update public.exercises set description='Glue your elbows to your sides and push down to a full lockout without leaning over the bar to add body weight.' where owner_id is null and name='Triceps pushdown';